INSERT INTO activity_types (id, code, name_de, name_en, desc_de, desc_en, category, allowed_zone_kinds, required_roles, required_docs, conditional, conflicts_with, detail_fields, checklist, lead_days, requires_site_clearance, sort_order) VALUES ('act-flight-specific', 'flight_specific', 'UAS-Flug (spezielle Kategorie)', 'UAS flight (specific category)', 'Z. B. BVLOS oder Abwurf inerter Lasten. Abwurf ist in der offenen Kategorie unzulässig (Art. 4 VO (EU) 2019/947).', 'E.g. BVLOS or dropping inert payloads. Dropping is not permitted in the open category (Art. 4 Regulation (EU) 2019/947).', 'flight', '["flight","robotics","water"]', '["project_lead","remote_pilot"]', '["operator_registration","pilot_competency","operation_authorisation","insurance"]', '[]', '["energetics"]', '[{"key":"uas_model","type":"text","de":"UAS-Typ / Modell","en":"UAS type / model","required":true},{"key":"mtom_kg","type":"number","de":"Startmasse (MTOM)","en":"Take-off mass (MTOM)","unit":"kg","required":true,"min":0,"max":25},{"key":"max_height_m","type":"number","de":"Maximale Flughöhe über Grund","en":"Maximum height above ground","unit":"m","required":true,"min":0},{"key":"operator_country","type":"select","de":"Registrierungsstaat des Betreibers","en":"Operator''s state of registration","required":true,"options":[{"value":"AT","de":"Österreich","en":"Austria"},{"value":"EU","de":"Anderer EU-/EASA-Staat","en":"Other EU/EASA state"}]},{"key":"operator_id","type":"text","de":"Betreiber-ID","en":"Operator ID","required":true},{"key":"operation_mode","type":"select","de":"Betriebsart","en":"Mode of operation","required":true,"options":[{"value":"VLOS","de":"VLOS (Sichtweite)","en":"VLOS"},{"value":"EVLOS","de":"EVLOS (erweiterte Sichtweite)","en":"EVLOS"},{"value":"BVLOS","de":"BVLOS (außer Sichtweite)","en":"BVLOS"}]},{"key":"inert_drop","type":"boolean","de":"Abwurf inerter Lasten","en":"Dropping of inert payloads"},{"key":"drop_mass_kg","type":"number","de":"Masse je Abwurf","en":"Mass per drop","unit":"kg","min":0},{"key":"authorisation_ref","type":"text","de":"Aktenzahl Betriebsgenehmigung / STS / Art. 13","en":"Reference of authorisation / STS / Art. 13","required":true}]', '[{"key":"authorisation_valid","de":"Betriebsgenehmigung deckt Betriebsart und Standort","en":"Authorisation covers mode of operation and site"},{"key":"airspace_check","de":"Luftraum und Geo-Zonen geprüft","en":"Airspace and geo-zones checked"},{"key":"ground_area_secured","de":"Bodenabsperrbereich und Abwurfzone markiert","en":"Ground safety area and drop zone marked"}]', 10, 0, 3);
